#!/usr/bin/env python3

# Some portions generated by Codex

from __future__ import annotations

import importlib.util
import json
import tempfile
import unittest
from pathlib import Path


REPOSITORY_ROOT = Path(__file__).resolve().parents[1]
SCRIPT = REPOSITORY_ROOT / "scripts" / "run-theme-execution-campaign.py"
BENCHMARK = "org.eclipse.rdf4j.sail.lmdb.benchmark.ThemeQueryPlanRunBenchmark.runQuery"
FIXED_PROPERTY = "-Drdf4j.benchmark.themeQueryPlanRun.planLifecycle=FIXED"


def load_campaign_module():
    spec = importlib.util.spec_from_file_location("theme_execution_campaign", SCRIPT)
    if spec is None or spec.loader is None:
        raise AssertionError(f"unable to load {SCRIPT}")
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


def write_json(path: Path, value: object) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(value) + "\n", encoding="utf-8")


def write_cell(results: Path, theme: str, query: int, samples: list[float]) -> None:
    result = results / f"{theme.lower()}-q{query}.json"
    write_json(
        result,
        [
            {
                "benchmark": BENCHMARK,
                "mode": "ss",
                "threads": 1,
                "forks": 1,
                "jvmArgs": ["-Xms1G", "-Xmx16G", FIXED_PROPERTY],
                "warmupIterations": 1,
                "measurementIterations": len(samples),
                "params": {"themeName": theme, "z_queryIndex": str(query)},
                "primaryMetric": {"rawData": [samples], "scoreUnit": "ms/op"},
                "secondaryMetrics": {
                    "gc.alloc.rate.norm": {
                        "rawData": [[100_000.0] * len(samples)],
                        "scoreUnit": "B/op",
                    }
                },
            }
        ],
    )
    write_json(
        result.with_suffix(".status.json"),
        {"formatVersion": 1, "outcome": "succeeded"},
    )


class ThemeExecutionCampaignTest(unittest.TestCase):

    def setUp(self) -> None:
        self.campaign = load_campaign_module()

    def test_summary_validates_fixed_plan_cell_and_raw_samples(self) -> None:
        with tempfile.TemporaryDirectory() as directory:
            results = Path(directory)
            write_cell(results, "SOCIAL_MEDIA", 4, [12.0, 10.0, 11.0, 9.0, 8.0])

            summary = self.campaign.summarize_campaign(
                results, (("SOCIAL_MEDIA", 4),), 1, 5
            )

            self.assertEqual("complete", summary["status"])
            self.assertEqual(1, summary["completeCellCount"])
            self.assertEqual(10.0, summary["cells"][0]["medianMillis"])
            self.assertEqual(12.0, summary["cells"][0]["p95Millis"])
            self.assertEqual([12.0, 10.0, 11.0, 9.0, 8.0], summary["cells"][0]["rawMillis"])

    def test_comparison_reports_strict_and_statistical_regression_views(self) -> None:
        baseline = {
            "status": "complete",
            "cells": [
                {
                    "theme": "LIBRARY",
                    "queryIndex": 10,
                    "status": "complete",
                    "medianMillis": 10.0,
                    "rawMillis": [8.0, 9.0, 10.0, 11.0, 12.0],
                }
            ],
        }
        candidate = {
            "status": "complete",
            "cells": [
                {
                    "theme": "LIBRARY",
                    "queryIndex": 10,
                    "status": "complete",
                    "medianMillis": 22.0,
                    "rawMillis": [20.0, 21.0, 22.0, 23.0, 24.0],
                }
            ],
        }

        comparison = self.campaign.compare_summaries(baseline, candidate)

        self.assertEqual("complete", comparison["status"])
        self.assertEqual(1, comparison["observedMedianRegressionCellCount"])
        self.assertEqual(1, comparison["significantRegressionCellCount"])
        self.assertFalse(comparison["observedMedianNoRegressionPass"])
        self.assertFalse(comparison["acceptancePass"])
        self.assertEqual("regression", comparison["cells"][0]["classification"])
        self.assertLessEqual(comparison["cells"][0]["oneSidedRegressionPValue"], 0.05)

    def test_summary_keeps_wrong_lifecycle_and_missing_cells_explicit(self) -> None:
        with tempfile.TemporaryDirectory() as directory:
            results = Path(directory)
            write_cell(results, "MEDICAL_RECORDS", 9, [1.0] * 5)
            result = results / "medical_records-q9.json"
            value = json.loads(result.read_text())
            value[0]["jvmArgs"].remove(FIXED_PROPERTY)
            write_json(result, value)

            summary = self.campaign.summarize_campaign(
                results,
                (("MEDICAL_RECORDS", 9), ("HIGHLY_CONNECTED", 10)),
                1,
                5,
            )

            self.assertEqual("incomplete", summary["status"])
            self.assertEqual(["jmh-stale"], summary["cells"][0]["issues"])
            self.assertEqual(["jmh-missing"], summary["cells"][1]["issues"])


if __name__ == "__main__":
    unittest.main()
